func (state uiState) adopt(link, region string) string {
	parsed, err := url.Parse(link)
	if err != nil || parsed.IsAbs() || parsed.Host != "" || !strings.HasPrefix(parsed.Path, "/") ||
		strings.HasPrefix(parsed.Path, "//") {
		return "/"
	}
	values := parsed.Query()
	switch {
	case parsed.Path == "/regions" || parsed.Path == "/regions/":
		parsed.Path = "/"
	case strings.HasPrefix(parsed.Path, "/regions/"):
		// Region pages name their region in the path, in lower case.
		region, rest, _ := strings.Cut(strings.TrimPrefix(parsed.Path, "/regions/"), "/")
		parsed.Path = "/regions/" + strings.ToLower(region) + strings.TrimSuffix("/"+rest, "/")
	}
	if subject := values.Get("subject"); subject != "" {
		values.Del("subject")
		if !values.Has("q") {
			values.Set("q", subjectSearch(subject))
		}
	}
	for name, value := range state.values() {
		if name != "r" && !values.Has(name) {
			values[name] = value
		}
	}
	if region != "" && !values.Has("r") {
		values.Set("r", region)
	}
	parsed.RawQuery = values.Encode()
	return parsed.String()
}

func validRegion(value string) bool {
	if value == "" || len(value) > 32 {
		return false
	}
	for _, char := range value {
		if !(char >= 'a' && char <= 'z' || char >= '0' && char <= '9' || char == '-') {
			return false
		}
	}
	return true
}

// validToken accepts IDs, digests, OCIDs and host names.
func validToken(value string) bool {
	if len(value) > 160 {
		return false
	}
	for _, char := range value {
		if !(char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' || char >= '0' && char <= '9' ||
			strings.ContainsRune("._-:/@", char)) {
			return false
		}
	}
	return true
}

