func drillView(now time.Time) *globalview.View {
	global := globalview.NewView("gru", func() []string { return []string{"sfo", "fra"} }, func() time.Time { return now })
	for _, cell := range []string{"gru", "sfo"} {
		observed := now
		if cell == "sfo" {
