func (state *regionState) backfill(now time.Time) {
	start := now.Add(-24 * time.Hour)
	for at := start; at.Before(now); {
		cluster := state.region.cluster(at, state.world.start)
		state.history.Append(at, state.sampler.Samples(cluster))
